  static string Quote(string s){ if(s.Length>0&&s.IndexOfAny(new[]{' ','\t','"'})<0)return s;var b=new StringBuilder("\"");int sl=0;foreach(char c in s){if(c=='\\'){sl++;continue;}if(c=='"'){b.Append('\\',sl*2+1).Append('"');sl=0;continue;}b.Append('\\',sl).Append(c);sl=0;}b.Append('\\',sl*2).Append('"');return b.ToString(); }
  static uint Active(IntPtr job){int n=Marshal.SizeOf(typeof(JOBOBJECT_BASIC_ACCOUNTING_INFORMATION));IntPtr p=Marshal.AllocHGlobal(n);try{if(!QueryInformationJobObject(job,JobObjectBasicAccountingInformation,p,(uint)n,IntPtr.Zero))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());return ((JOBOBJECT_BASIC_ACCOUNTING_INFORMATION)Marshal.PtrToStructure(p,typeof(JOBOBJECT_BASIC_ACCOUNTING_INFORMATION))).ActiveProcesses;}finally{Marshal.FreeHGlobal(p);}}
  static void Receipt(string path,Dictionary<string,object> value){string temp=Path.Combine(Path.GetDirectoryName(path),".j-"+Process.GetCurrentProcess().Id+"-"+Guid.NewGuid().ToString("N"));File.WriteAllText(temp,new JavaScriptSerializer().Serialize(value),new UTF8Encoding(false));if(File.Exists(path))File.Delete(path);File.Move(temp,path);}
  public static int Main(string[] argv){var receipt=new Dictionary<string,object>{{"version",1},{"rootPid",null},{"rootExited",false},{"activeProcesses",null},{"activeBeforeStop",null},{"jobConfirmed",false},{"cancelReceived",false},{"exitCode",null},{"helperError",null},{"ready",false},{"resumed",false}};IntPtr job=IntPtr.Zero,attrs=IntPtr.Zero,handles=IntPtr.Zero;bool assigned=false;PROCESS_INFORMATION pi=new PROCESS_INFORMATION();string receiptPath=argv.Length>2?argv[2]:null;try{
    bool forceAssignFailure=argv.Length==4&&argv[3]=="--test-assign-failure";if(argv.Length!=3&&!forceAssignFailure)throw new ArgumentException("usage: supervisor REQUEST_BASE64 PIPE RECEIPT");var json=Encoding.UTF8.GetString(Convert.FromBase64String(argv[0]));var req=(Dictionary<string,object>)new JavaScriptSerializer().DeserializeObject(json);string file=(string)req["file"],cwd=(string)req["cwd"],pipe=argv[1];var args=(object[])req["args"];var cmd=new StringBuilder(Quote(file));foreach(var x in args)cmd.Append(' ').Append(Quote((string)x));
    job=CreateJobObject(IntPtr.Zero,null);if(job==IntPtr.Zero)throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());var limit=new JOBOBJECT_EXTENDED_LIMIT_INFORMATION();limit.BasicLimitInformation.LimitFlags=JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;int ln=Marshal.SizeOf(limit);IntPtr lp=Marshal.AllocHGlobal(ln);try{Marshal.StructureToPtr(limit,lp,false);if(!SetInformationJobObject(job,JobObjectExtendedLimitInformation,lp,(uint)ln))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());}finally{Marshal.FreeHGlobal(lp);}
    var std=new[]{GetStdHandle(-10),GetStdHandle(-11),GetStdHandle(-12)};foreach(var h in std)if(h==IntPtr.Zero||h==new IntPtr(-1)||!SetHandleInformation(h,HANDLE_FLAG_INHERIT,HANDLE_FLAG_INHERIT))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());IntPtr size=IntPtr.Zero;InitializeProcThreadAttributeList(IntPtr.Zero,1,0,ref size);attrs=Marshal.AllocHGlobal(size);if(!InitializeProcThreadAttributeList(attrs,1,0,ref size))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());handles=Marshal.AllocHGlobal(IntPtr.Size*3);for(int i=0;i<3;i++)Marshal.WriteIntPtr(handles,i*IntPtr.Size,std[i]);if(!UpdateProcThreadAttribute(attrs,0,new IntPtr(PROC_THREAD_ATTRIBUTE_HANDLE_LIST),handles,new IntPtr(IntPtr.Size*3),IntPtr.Zero,IntPtr.Zero))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());
    var si=new STARTUPINFOEX();si.StartupInfo.cb=Marshal.SizeOf(si);si.StartupInfo.dwFlags=STARTF_USESTDHANDLES;si.StartupInfo.hStdInput=std[0];si.StartupInfo.hStdOutput=std[1];si.StartupInfo.hStdError=std[2];si.lpAttributeList=attrs;if(!CreateProcessW(file,cmd,IntPtr.Zero,IntPtr.Zero,true,CREATE_SUSPENDED|CREATE_NO_WINDOW|EXTENDED_STARTUPINFO_PRESENT,IntPtr.Zero,cwd,ref si,out pi))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());receipt["rootPid"]=(int)pi.dwProcessId;if(forceAssignFailure)throw new Exception("test assign failure");if(!AssignProcessToJobObject(job,pi.hProcess))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());assigned=true;
    int cancel=0;var security=new PipeSecurity();var sid=WindowsIdentity.GetCurrent().User;security.SetAccessRuleProtection(true,false);security.AddAccessRule(new PipeAccessRule(sid,PipeAccessRights.ReadWrite,AccessControlType.Allow));var server=new NamedPipeServerStream(pipe,PipeDirection.InOut,1,PipeTransmissionMode.Byte,PipeOptions.Asynchronous,1,1,security);receipt["ready"]=true;Receipt(receiptPath,receipt);IAsyncResult pending=server.BeginWaitForConnection(null,null);if(!pending.AsyncWaitHandle.WaitOne(12000)){server.Dispose();try{server.EndWaitForConnection(pending);}catch{}pending.AsyncWaitHandle.Close();throw new TimeoutException("control pipe connection timeout");}server.EndWaitForConnection(pending);pending.AsyncWaitHandle.Close();int command=server.ReadByte();if(command==1){Interlocked.Exchange(ref cancel,1);receipt["cancelReceived"]=true;receipt["activeBeforeStop"]=(int)Active(job);if(!TerminateJobObject(job,130))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());server.Dispose();}else if(command==2){if(ResumeThread(pi.hThread)==0xffffffff)throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());receipt["resumed"]=true;var thread=new Thread(()=>{try{server.ReadByte();Interlocked.Exchange(ref cancel,1);}catch{Interlocked.Exchange(ref cancel,1);}finally{server.Dispose();}});thread.IsBackground=true;thread.Start();}else{server.Dispose();throw new Exception("invalid control command:"+command);}
    while(true){uint w=WaitForSingleObject(pi.hProcess,100);if(Interlocked.CompareExchange(ref cancel,0,0)==1){receipt["cancelReceived"]=true;receipt["activeBeforeStop"]=(int)Active(job);if(!TerminateJobObject(job,130))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());break;}if(w==WAIT_OBJECT_0)break;if(w!=WAIT_TIMEOUT)throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());}receipt["rootExited"]=WaitForSingleObject(pi.hProcess,0)==WAIT_OBJECT_0;if(!(bool)receipt["rootExited"]){WaitForSingleObject(pi.hProcess,10000);receipt["rootExited"]=WaitForSingleObject(pi.hProcess,0)==WAIT_OBJECT_0;}uint remaining=Active(job);if((bool)receipt["rootExited"]&&remaining>0){receipt["activeBeforeStop"]=(int)remaining;if(!TerminateJobObject(job,131))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());}for(int i=0;i<100&&Active(job)>0;i++)Thread.Sleep(100);uint active=Active(job);receipt["activeProcesses"]=(int)active;receipt["jobConfirmed"]=active==0&&(bool)receipt["rootExited"];uint exit;if(GetExitCodeProcess(pi.hProcess,out exit))receipt["exitCode"]=(int)exit;if(!(bool)receipt["jobConfirmed"])throw new Exception("job not empty");Receipt(receiptPath,receipt);return 0;
  }catch(Exception e){receipt["helperError"]=e.GetType().Name+":"+e.Message;try{if(pi.hProcess!=IntPtr.Zero&&!assigned){TerminateProcess(pi.hProcess,132);WaitForSingleObject(pi.hProcess,10000);}else if(job!=IntPtr.Zero){TerminateJobObject(job,132);if(pi.hProcess!=IntPtr.Zero)WaitForSingleObject(pi.hProcess,10000);}receipt["rootExited"]=pi.hProcess!=IntPtr.Zero&&WaitForSingleObject(pi.hProcess,0)==WAIT_OBJECT_0;if(job!=IntPtr.Zero)receipt["activeProcesses"]=(int)Active(job);}catch{}try{if(receiptPath!=null)Receipt(receiptPath,receipt);}catch{}return 125;}finally{if(pi.hThread!=IntPtr.Zero)CloseHandle(pi.hThread);if(pi.hProcess!=IntPtr.Zero)CloseHandle(pi.hProcess);if(attrs!=IntPtr.Zero){DeleteProcThreadAttributeList(attrs);Marshal.FreeHGlobal(attrs);}if(handles!=IntPtr.Zero)Marshal.FreeHGlobal(handles);if(job!=IntPtr.Zero)CloseHandle(job);}}
}
